// Parses Docs/design/04-api-mapping/state-to-ui.md into chip labels and tones. Used by scripts/gen-status.ts
// to write registry.generated.ts, and by a test that fails when the generated file drifts from the doc.

export const TONES = ["ok", "warn", "bad", "neutral", "info"] as const;
export type Tone = (typeof TONES)[number];

export type ChipSpec = {
  /** The first label in the doc's "Chip label (tone)" cell, without quotes; null when the cell has no clean
   *  label (it then needs an entry in overrides.ts before a chip can show it). */
  label: string | null;
  /** null when the doc gives no tone for that label (for example a timeline step). */
  tone: Tone | null;
  /** The whole cell, for context (audience-specific labels are spelled out there). */
  raw: string;
};

export type Registry = Record<string, Record<string, ChipSpec>>;

// "## Escrow release" -> "escrow_release"
const entityKey = (heading: string) =>
  heading
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_|_$/g, "");

const STATE = /^`([a-z_]+)`$/;
// A label right before its tone, with an optional "Audience:" prefix and an optional "/ other label":
//   Claimed (warn) · …   |   Client: "Under review by iBackHome" (warn)   |   "Releasing" / Approved (info)
const LABEL_TONE = /^(?:[A-Za-z ]+:\s*)?"?([^"(;/]+?)"?\s*(?:\/\s*[^(;]+?)?\s*\((ok|warn|bad|neutral|info)\b/;
// Otherwise only a leading quoted label counts, with no tone:   "Sent to the escrow partner" (timeline step)
const QUOTED = /^(?:[A-Za-z ]+:\s*)?"([^"]+)"/;

export function parseStateToUi(markdown: string): Registry {
  const registry: Registry = {};
  let entity: string | null = null;

  for (const line of markdown.replace(/\r/g, "").split("\n")) {
    const heading = /^## (.+)$/.exec(line);
    if (heading) {
      const key = entityKey(heading[1] ?? "");
      // Only sections with a state table; "Device-only states" and the tone notes have none.
      entity = key.startsWith("device_only") || key.startsWith("tone_") ? null : key;
      continue;
    }
    if (!entity || !line.startsWith("| `")) continue;

    const cells = line
      .split("|")
      .slice(1, -1)
      .map((c) => c.trim());
    const state = STATE.exec(cells[0] ?? "");
    // Skips rows whose state isn't a real backend status, e.g. "`(not in Spec) on hold`".
    if (!state?.[1]) continue;
    const raw = cells[1] ?? "";
    const match = LABEL_TONE.exec(raw);
    const quoted = match ? null : QUOTED.exec(raw);
    (registry[entity] ??= {})[state[1]] = match?.[1]
      ? { label: match[1].trim(), tone: match[2] as Tone, raw }
      : { label: quoted?.[1]?.trim() ?? null, tone: null, raw };
  }
  return registry;
}

export function renderRegistry(registry: Registry): string {
  return [
    "// Generated by scripts/gen-status.ts from Docs/design/04-api-mapping/state-to-ui.md. Do not edit.",
    "// Run `bun run gen:status` after changing the doc; src/common/status/registry.test.ts checks for drift.",
    'import type { Registry } from "./parse";',
    "",
    `export const REGISTRY = ${JSON.stringify(registry, null, 2)} as const satisfies Registry;`,
    "",
  ].join("\n");
}
